  color: var(--white);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .heading-xl { font-size: var(--fs-4xl); }
  .heading-lg { font-size: var(--fs-3xl); }

  .features-grid {
    grid-template-columns: repeat(2, 1fr);
