  .nav__burger {
    display: flex;
  }

  .section {
    padding: var(--sp-3xl) 0;
  }

  .hero {
    min-height: 70vh;
    padding: var(--sp-3xl) var(--sp-md);
  }

  .hero__subtitle {
    font-size: var(--fs-base);
  }

  .two-ways__grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .instructor-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--sp-md);
  }

  .carousel__slide {
    min-width: 100%;
  }

  .schedule__table thead th,
  .schedule__table tbody td {
    padding: var(--sp-md);
    font-size: var(--fs-sm);
  }

  .footer__grid {
    grid-template-columns: 1fr;
    gap: var(--sp-2xl);
  }

  .newsletter__form {
    flex-direction: column;
  }

  .toggle-tabs {
    display: flex;
    width: 100%;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .toggle-tab {
    flex: 1;
    padding: var(--sp-md);
    font-size: var(--fs-sm);
  }

  .filter-controls {
    gap: var(--sp-xs);
  }

  .filter-btn {
    font-size: var(--fs-xs);
    padding: var(--sp-xs) var(--sp-md);
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 var(--sp-md);
  }

  .heading-xl { font-size: var(--fs-2xl); }
  .heading-lg { font-size: var(--fs-xl); }

  .hero {
    min-height: 60vh;
  }

  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .hero__actions {
    flex-direction: column;
    align-items: center;
  }

  .cta-section__actions {
    flex-direction: column;
    align-items: center;
  }
}

/* --- Utility --- */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

