/* ============================================
   RedRoom Fitness — Design System & Styles
   ============================================ */

/* --- OKLCH Color Palette --- */
:root {
  /* Primary */
  --red: oklch(55% 0.24 27);
  --red-bright: oklch(63% 0.26 27);
  --red-dark: oklch(40% 0.2 27);
  --red-glow: oklch(55% 0.24 27 / 0.4);

  /* Neutrals */
  --black: oklch(8% 0.01 27);
  --charcoal: oklch(12% 0.01 27);
  --dark-gray: oklch(18% 0.01 27);
  --mid-gray: oklch(28% 0.01 27);
  --gray: oklch(45% 0.01 27);
  --light-gray: oklch(72% 0.01 27);
  --off-white: oklch(90% 0.005 27);
  --white: oklch(100% 0 0);

  /* Semantic */
  --bg-primary: var(--charcoal);
  --bg-surface: var(--dark-gray);
  --bg-elevated: var(--mid-gray);
  --text-primary: var(--white);
  --text-secondary: var(--light-gray);
  --text-muted: var(--gray);
  --accent: var(--red);
  --accent-hover: var(--red-bright);
  --border-color: oklch(25% 0.02 27);

  /* Spacing Scale */
  --sp-xs: 0.25rem;
  --sp-sm: 0.5rem;
  --sp-md: 1rem;
  --sp-lg: 1.5rem;
  --sp-xl: 2rem;
  --sp-2xl: 3rem;
  --sp-3xl: 4rem;
  --sp-4xl: 6rem;
  --sp-5xl: 8rem;

  /* Type Scale */
  --fs-xs: 0.75rem;
  --fs-sm: 0.875rem;
  --fs-base: 1rem;
  --fs-md: 1.125rem;
  --fs-lg: 1.25rem;
  --fs-xl: 1.5rem;
  --fs-2xl: 2rem;
  --fs-3xl: 2.5rem;
  --fs-4xl: 3.5rem;
  --fs-5xl: 5rem;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 150ms;
  --duration-base: 300ms;
  --duration-slow: 500ms;

  /* Layout */
  --max-width: 1200px;
  --nav-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  font-size: var(--fs-base);
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-primary);
  overflow-x: hidden;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  color: inherit;
}

ul, ol {
  list-style: none;
}

/* --- Typography --- */
.heading-xl {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-5xl);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.02em;
  text-transform: uppercase;
}

.heading-lg {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-4xl);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.01em;
  text-transform: uppercase;
}

.heading-md {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-3xl);
  font-weight: 700;
  line-height: 1.1;
  text-transform: uppercase;
}

.heading-sm {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-2xl);
  font-weight: 600;
  line-height: 1.15;
  text-transform: uppercase;
}

.heading-xs {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-xl);
  font-weight: 600;
  line-height: 1.2;
  text-transform: uppercase;
}

.text-lg { font-size: var(--fs-lg); }
.text-md { font-size: var(--fs-md); }
.text-sm { font-size: var(--fs-sm); }
.text-xs { font-size: var(--fs-xs); }

.text-accent { color: var(--accent); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-xl);
}

.section {
  padding: var(--sp-5xl) 0;
}

.section--compact {
  padding: var(--sp-3xl) 0;
}

/* --- Top Bar Promo --- */
.top-bar {
  background: var(--red);
  color: var(--white);
  text-align: center;
  padding: var(--sp-sm) var(--sp-md);
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.top-bar a {
  text-decoration: underline;
  text-underline-offset: 2px;
  margin-left: var(--sp-sm);
  font-weight: 700;
}

.top-bar a:hover {
  opacity: 0.85;
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: oklch(8% 0.01 27 / 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--nav-height);
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-xl);
}

.nav__logo {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-xl);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--white);
  flex-shrink: 0;
}

.nav__logo span {
  color: var(--red);
}

.nav__links {
  display: flex;
  align-items: center;
  gap: var(--sp-lg);
}

.nav__links a {
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-secondary);
  transition: color var(--duration-fast) ease;
  white-space: nowrap;
}

.nav__links a:hover,
.nav__links a.active {
  color: var(--white);
}

.nav__actions {
  display: flex;
  align-items: center;
  gap: var(--sp-md);
}

.nav__burger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--sp-sm);
}

.nav__burger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: all var(--duration-base) var(--ease-out);
}

.nav__burger.open span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav__burger.open span:nth-child(2) {
  opacity: 0;
}

.nav__burger.open span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile nav */
.nav__mobile {
  display: none;
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: oklch(8% 0.01 27 / 0.98);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  z-index: 999;
  padding: var(--sp-xl);
  flex-direction: column;
  gap: var(--sp-lg);
  overflow-y: auto;
}

.nav__mobile.open {
  display: flex;
}

.nav__mobile a {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-2xl);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--text-secondary);
  padding: var(--sp-sm) 0;
  border-bottom: 1px solid var(--border-color);
  transition: color var(--duration-fast) ease;
}

.nav__mobile a:hover {
  color: var(--white);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-sm);
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-md);
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: var(--sp-md) var(--sp-2xl);
  border-radius: var(--radius-sm);
  transition: all var(--duration-base) var(--ease-out);
  white-space: nowrap;
}

.btn--primary {
  background: var(--red);
  color: var(--white);
}

.btn--primary:hover {
  background: var(--red-bright);
  transform: translateY(-1px);
  box-shadow: 0 8px 24px var(--red-glow);
}

.btn--outline {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}

.btn--outline:hover {
  background: var(--white);
  color: var(--charcoal);
}

.btn--ghost {
  background: transparent;
  color: var(--white);
  border: 1px solid oklch(45% 0.02 27);
}

.btn--ghost:hover {
  border-color: var(--white);
}

.btn--sm {
  font-size: var(--fs-sm);
  padding: var(--sp-sm) var(--sp-lg);
}

.btn--lg {
  font-size: var(--fs-lg);
  padding: var(--sp-lg) var(--sp-3xl);
}

/* --- Hero Section --- */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  padding: var(--sp-4xl) var(--sp-xl);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 50% 40%, oklch(55% 0.24 27 / 0.15), transparent 70%),
    radial-gradient(ellipse 60% 80% at 20% 80%, oklch(55% 0.24 27 / 0.08), transparent 60%),
    radial-gradient(ellipse 60% 80% at 80% 80%, oklch(55% 0.24 27 / 0.08), transparent 60%);
  z-index: 0;
}

.hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, var(--bg-primary));
  z-index: 1;
}

.hero__content {
  position: relative;
  z-index: 2;
  max-width: 900px;
}

.hero__title {
  margin-bottom: var(--sp-lg);
}

.hero__title .accent {
  color: var(--red);
}

.hero__subtitle {
  font-size: var(--fs-lg);
  color: var(--text-secondary);
  max-width: 650px;
  margin: 0 auto var(--sp-2xl);
  line-height: 1.6;
}

.hero__actions {
  display: flex;
  gap: var(--sp-md);
  justify-content: center;
  flex-wrap: wrap;
}

/* --- Community Promo --- */
.community-promo {
  text-align: center;
  background: var(--bg-surface);
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
}

.community-promo__heading {
  margin-bottom: var(--sp-lg);
}

.community-promo__body {
  max-width: 680px;
  margin: 0 auto var(--sp-xl);
  color: var(--text-secondary);
  font-size: var(--fs-md);
  line-height: 1.7;
}

/* --- Two Ways --- */
.two-ways {
  text-align: center;
}

.two-ways__heading {
  margin-bottom: var(--sp-3xl);
}

.two-ways__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-xl);
}

.two-ways__card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: var(--sp-3xl) var(--sp-2xl);
  text-align: center;
  transition: all var(--duration-base) var(--ease-out);
  position: relative;
  overflow: hidden;
}

.two-ways__card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--duration-base) var(--ease-out);
}

.two-ways__card:hover::before {
  transform: scaleX(1);
}

.two-ways__card:hover {
  border-color: oklch(35% 0.04 27);
  transform: translateY(-4px);
}

.two-ways__card-label {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-xs);
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: var(--sp-lg);
}

.two-ways__card-title {
  margin-bottom: var(--sp-md);
}

.two-ways__card-body {
  color: var(--text-secondary);
  line-height: 1.7;
}

/* --- Studio Experience --- */
.studio-experience {
  text-align: center;
  position: relative;
  overflow: hidden;
}

.studio-experience::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 50% at 50% 50%, oklch(55% 0.24 27 / 0.06), transparent 70%);
  z-index: 0;
}

.studio-experience__content {
  position: relative;
  z-index: 1;
  max-width: 720px;
  margin: 0 auto;
}

.studio-experience__heading {
  margin-bottom: var(--sp-lg);
}

.studio-experience__body {
  color: var(--text-secondary);
  font-size: var(--fs-md);
  line-height: 1.7;
  margin-bottom: var(--sp-xl);
}

/* --- Free Trial CTA --- */
.free-trial {
  text-align: center;
  background: var(--red);
  position: relative;
  overflow: hidden;
}

.free-trial::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 50% 100% at 20% 50%, oklch(70% 0.26 27 / 0.3), transparent),
    radial-gradient(ellipse 50% 100% at 80% 50%, oklch(70% 0.26 27 / 0.3), transparent);
}

.free-trial__content {
  position: relative;
  z-index: 1;
}

.free-trial__heading {
  margin-bottom: var(--sp-xl);
  color: var(--white);
}

.free-trial .btn--outline {
  border-color: var(--white);
  color: var(--white);
}

.free-trial .btn--outline:hover {
  background: var(--white);
  color: var(--red);
}

/* --- Lifestyle Carousel --- */
.carousel {
  overflow: hidden;
  position: relative;
}

.carousel__heading {
  text-align: center;
  margin-bottom: var(--sp-2xl);
}

.carousel__track-wrapper {
  overflow: hidden;
  border-radius: var(--radius-lg);
}

.carousel__track {
  display: flex;
  transition: transform var(--duration-slow) var(--ease-out);
}

.carousel__slide {
  min-width: 33.333%;
  flex-shrink: 0;
  position: relative;
  aspect-ratio: 4 / 3;
  background: var(--bg-surface);
  overflow: hidden;
}

.carousel__slide-bg {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: oklch(55% 0.24 27 / 0.3);
  position: relative;
}

.carousel__slide-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, oklch(55% 0.24 27 / 0.15), oklch(12% 0.01 27 / 0.6));
}

.carousel__slide-bg span {
  position: relative;
  z-index: 1;
}

.carousel__controls {
  display: flex;
  justify-content: center;
  gap: var(--sp-md);
  margin-top: var(--sp-xl);
}

.carousel__btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--duration-base) var(--ease-out);
  color: var(--text-secondary);
  font-size: var(--fs-lg);
}

.carousel__btn:hover {
  border-color: var(--red);
  color: var(--red);
  background: oklch(55% 0.24 27 / 0.1);
}

.carousel__dots {
  display: flex;
  justify-content: center;
  gap: var(--sp-sm);
  margin-top: var(--sp-lg);
}

.carousel__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border-color);
  transition: all var(--duration-base) var(--ease-out);
  cursor: pointer;
}

.carousel__dot.active {
  background: var(--red);
  width: 24px;
  border-radius: 4px;
}

/* --- Method Overview --- */
.method-overview {
  text-align: center;
}

.method-overview__heading {
  margin-bottom: var(--sp-lg);
}

.method-overview__body {
  max-width: 720px;
  margin: 0 auto;
  color: var(--text-secondary);
  font-size: var(--fs-md);
  line-height: 1.7;
}

/* --- Weekly Schedule Table --- */
.schedule {
  overflow-x: auto;
}

.schedule__heading {
  text-align: center;
  margin-bottom: var(--sp-2xl);
}

.schedule__table {
  width: 100%;
  border-collapse: collapse;
  background: var(--bg-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border-color);
}

.schedule__table thead th {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-sm);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-secondary);
  padding: var(--sp-lg) var(--sp-xl);
  text-align: left;
  border-bottom: 2px solid var(--red);
  background: oklch(15% 0.01 27);
}

.schedule__table tbody td {
  padding: var(--sp-lg) var(--sp-xl);
  border-bottom: 1px solid var(--border-color);
  font-size: var(--fs-md);
}

.schedule__table tbody tr:last-child td {
  border-bottom: none;
}

.schedule__table tbody tr:hover {
  background: oklch(15% 0.02 27);
}

.schedule__table .day-name {
  font-family: 'Oswald', sans-serif;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--white);
}

.schedule__table .muscle-group {
  color: var(--text-secondary);
}

.schedule__table .muscle-accent {
  color: var(--red);
  font-weight: 600;
}

/* --- Floor/Treadmill Toggle --- */
.toggle-section {
  text-align: center;
}

.toggle-section__heading {
  margin-bottom: var(--sp-xl);
}

.toggle-tabs {
  display: inline-flex;
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: var(--sp-xs);
  margin-bottom: var(--sp-3xl);
}

.toggle-tab {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-md);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: var(--sp-md) var(--sp-2xl);
  border-radius: var(--radius-sm);
  transition: all var(--duration-base) var(--ease-out);
  color: var(--text-muted);
}

.toggle-tab.active {
  background: var(--red);
  color: var(--white);
}

.toggle-tab:hover:not(.active) {
  color: var(--text-primary);
}

.toggle-content {
  display: none;
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.toggle-content.active {
  display: block;
  animation: fadeIn var(--duration-base) var(--ease-out);
}

.toggle-content__title {
  margin-bottom: var(--sp-md);
}

.toggle-content__body {
  color: var(--text-secondary);
  font-size: var(--fs-md);
  line-height: 1.7;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Instructor Grid --- */
.instructors-section {
  text-align: center;
}

.instructors-section__heading {
  margin-bottom: var(--sp-3xl);
}

.filter-controls {
  display: flex;
  justify-content: center;
  gap: var(--sp-sm);
  margin-bottom: var(--sp-3xl);
  flex-wrap: wrap;
}

.filter-btn {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: var(--sp-sm) var(--sp-lg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  transition: all var(--duration-base) var(--ease-out);
  background: transparent;
}

.filter-btn:hover {
  border-color: var(--text-secondary);
  color: var(--text-primary);
}

.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--sp-xl);
}

.instructor-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--duration-base) var(--ease-out);
}

.instructor-card:hover {
  transform: translateY(-4px);
  border-color: oklch(35% 0.04 27);
  box-shadow: 0 12px 32px oklch(0% 0 0 / 0.3);
}

.instructor-card__photo {
  aspect-ratio: 1;
  background: linear-gradient(135deg, oklch(20% 0.02 27), oklch(30% 0.03 27));
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.instructor-card__photo::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, oklch(12% 0.01 27 / 0.8));
}

.instructor-card__initials {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-3xl);
  font-weight: 700;
  color: oklch(55% 0.24 27 / 0.25);
  position: relative;
  z-index: 1;
}

.instructor-card__info {
  padding: var(--sp-lg);
}

.instructor-card__name {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-lg);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  margin-bottom: var(--sp-xs);
}

.instructor-card__location {
  font-size: var(--fs-sm);
  color: var(--red);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: var(--sp-md);
}

.instructor-card__book {
  display: inline-block;
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--red);
  transition: color var(--duration-fast) ease;
}

.instructor-card__book:hover {
  color: var(--red-bright);
}

/* --- FAQ Accordion --- */
.faq-section {
  max-width: 800px;
  margin: 0 auto;
}

.faq-section__heading {
  text-align: center;
  margin-bottom: var(--sp-3xl);
}

.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-item:first-child {
  border-top: 1px solid var(--border-color);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--sp-xl) 0;
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-lg);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  text-align: left;
  color: var(--text-primary);
  transition: color var(--duration-fast) ease;
}

.faq-question:hover {
  color: var(--red);
}

.faq-question__icon {
  font-size: var(--fs-xl);
  color: var(--red);
  transition: transform var(--duration-base) var(--ease-out);
  flex-shrink: 0;
  margin-left: var(--sp-md);
}

.faq-item.open .faq-question__icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--duration-slow) var(--ease-out), padding var(--duration-slow) var(--ease-out);
}

.faq-answer__inner {
  padding-bottom: var(--sp-xl);
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: var(--fs-md);
}

.faq-item.open .faq-answer {
  max-height: 300px;
}

/* --- Digital Features --- */
.features-section {
  text-align: center;
}

.features-section__heading {
  margin-bottom: var(--sp-3xl);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--sp-xl);
}

.feature-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: var(--sp-2xl);
  text-align: center;
  transition: all var(--duration-base) var(--ease-out);
  position: relative;
}

.feature-card:hover {
  border-color: oklch(35% 0.04 27);
  transform: translateY(-4px);
}

.feature-card__icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  background: oklch(55% 0.24 27 / 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--sp-lg);
  font-size: var(--fs-2xl);
  color: var(--red);
}

.feature-card__title {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-lg);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  margin-bottom: var(--sp-md);
}

.feature-card__body {
  color: var(--text-secondary);
  font-size: var(--fs-sm);
  line-height: 1.7;
}

/* --- CTA Section --- */
.cta-section {
  text-align: center;
}

.cta-section__heading {
  margin-bottom: var(--sp-lg);
}

.cta-section__body {
  color: var(--text-secondary);
  font-size: var(--fs-md);
  max-width: 600px;
  margin: 0 auto var(--sp-xl);
  line-height: 1.7;
}

.cta-section__actions {
  display: flex;
  gap: var(--sp-md);
  justify-content: center;
  flex-wrap: wrap;
}

/* --- Newsletter --- */
.newsletter {
  text-align: center;
  border-top: 1px solid var(--border-color);
}

.newsletter__heading {
  margin-bottom: var(--sp-md);
}

.newsletter__body {
  color: var(--text-secondary);
  margin-bottom: var(--sp-xl);
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

.newsletter__form {
  display: flex;
  max-width: 480px;
  margin: 0 auto;
  gap: var(--sp-sm);
}

.newsletter__input {
  flex: 1;
  padding: var(--sp-md) var(--sp-lg);
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: var(--fs-base);
  font-family: inherit;
  outline: none;
  transition: border-color var(--duration-fast) ease;
}

.newsletter__input::placeholder {
  color: var(--text-muted);
}

.newsletter__input:focus {
  border-color: var(--red);
}

.newsletter__input.error {
  border-color: oklch(60% 0.2 25);
}

.newsletter__input.success {
  border-color: oklch(65% 0.18 145);
}

.newsletter__msg {
  font-size: var(--fs-sm);
  margin-top: var(--sp-sm);
  min-height: 1.4em;
}

.newsletter__msg.error {
  color: oklch(65% 0.2 25);
}

.newsletter__msg.success {
  color: oklch(70% 0.18 145);
}

/* --- Footer --- */
.footer {
  background: oklch(6% 0.01 27);
  border-top: 1px solid var(--border-color);
  padding: var(--sp-4xl) 0 var(--sp-xl);
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: var(--sp-3xl);
  margin-bottom: var(--sp-3xl);
}

.footer__brand-name {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-2xl);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--sp-md);
}

.footer__brand-name span {
  color: var(--red);
}

.footer__brand-body {
  color: var(--text-muted);
  font-size: var(--fs-sm);
  line-height: 1.7;
  max-width: 300px;
}

.footer__col-title {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-sm);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-secondary);
  margin-bottom: var(--sp-lg);
}

.footer__col a {
  display: block;
  font-size: var(--fs-sm);
  color: var(--text-muted);
  padding: var(--sp-xs) 0;
  transition: color var(--duration-fast) ease;
}

.footer__col a:hover {
  color: var(--white);
}

.footer__bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--sp-xl);
  border-top: 1px solid var(--border-color);
  flex-wrap: wrap;
  gap: var(--sp-md);
}

.footer__copyright {
  font-size: var(--fs-xs);
  color: var(--text-muted);
}

.footer__country {
  position: relative;
}

.footer__country-btn {
  display: flex;
  align-items: center;
  gap: var(--sp-sm);
  font-size: var(--fs-sm);
  color: var(--text-muted);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: var(--sp-sm) var(--sp-md);
  transition: all var(--duration-fast) ease;
}

.footer__country-btn:hover {
  border-color: var(--text-secondary);
  color: var(--text-primary);
}

.footer__country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  right: 0;
  background: var(--dark-gray);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  margin-bottom: var(--sp-xs);
  display: none;
  overflow: hidden;
  z-index: 100;
}

.footer__country-dropdown.open {
  display: block;
}

.footer__country-option {
  display: block;
  width: 100%;
  text-align: left;
  padding: var(--sp-sm) var(--sp-md);
  font-size: var(--fs-sm);
  color: var(--text-secondary);
  transition: all var(--duration-fast) ease;
  border: none;
  background: none;
}

.footer__country-option:hover,
.footer__country-option.active {
  background: oklch(55% 0.24 27 / 0.15);
  color: var(--white);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .heading-xl { font-size: var(--fs-4xl); }
  .heading-lg { font-size: var(--fs-3xl); }

  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .instructor-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .carousel__slide {
    min-width: 50%;
  }

  .footer__grid {
    grid-template-columns: 1fr 1fr;
    gap: var(--sp-2xl);
  }
}

@media (max-width: 768px) {
  :root {
    --nav-height: 64px;
  }

  .heading-xl { font-size: var(--fs-3xl); }
  .heading-lg { font-size: var(--fs-2xl); }
  .heading-md { font-size: var(--fs-xl); }

  .nav__links,
  .nav__actions .btn {
    display: none;
  }

  .nav__burger {
    display: flex;
  }

  .section {
    padding: var(--sp-3xl) 0;
  }

  .hero {
    min-height: 70vh;
    padding: var(--sp-3xl) var(--sp-md);
  }

  .hero__subtitle {
    font-size: var(--fs-base);
  }

  .two-ways__grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .instructor-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--sp-md);
  }

  .carousel__slide {
    min-width: 100%;
  }

  .schedule__table thead th,
  .schedule__table tbody td {
    padding: var(--sp-md);
    font-size: var(--fs-sm);
  }

  .footer__grid {
    grid-template-columns: 1fr;
    gap: var(--sp-2xl);
  }

  .newsletter__form {
    flex-direction: column;
  }

  .toggle-tabs {
    display: flex;
    width: 100%;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .toggle-tab {
    flex: 1;
    padding: var(--sp-md);
    font-size: var(--fs-sm);
  }

  .filter-controls {
    gap: var(--sp-xs);
  }

  .filter-btn {
    font-size: var(--fs-xs);
    padding: var(--sp-xs) var(--sp-md);
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 var(--sp-md);
  }

  .heading-xl { font-size: var(--fs-2xl); }
  .heading-lg { font-size: var(--fs-xl); }

  .hero {
    min-height: 60vh;
  }

  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .hero__actions {
    flex-direction: column;
    align-items: center;
  }

  .cta-section__actions {
    flex-direction: column;
    align-items: center;
  }
}

/* --- Utility --- */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ============================================
   RedRoom Fitness — Design System & Styles
   ============================================ */

/* --- OKLCH Color Palette --- */
:root {
  /* Primary */
  --red: oklch(55% 0.24 27);
  --red-bright: oklch(63% 0.26 27);
  --red-dark: oklch(40% 0.2 27);
  --red-glow: oklch(55% 0.24 27 / 0.4);

  /* Neutrals */
  --black: oklch(8% 0.01 27);
  --charcoal: oklch(12% 0.01 27);
  --dark-gray: oklch(18% 0.01 27);
  --mid-gray: oklch(28% 0.01 27);
  --gray: oklch(45% 0.01 27);
  --light-gray: oklch(72% 0.01 27);
  --off-white: oklch(90% 0.005 27);
  --white: oklch(100% 0 0);

  /* Semantic */
  --bg-primary: var(--charcoal);
  --bg-surface: var(--dark-gray);
  --bg-elevated: var(--mid-gray);
  --text-primary: var(--white);
  --text-secondary: var(--light-gray);
  --text-muted: var(--gray);
  --accent: var(--red);
  --accent-hover: var(--red-bright);
  --border-color: oklch(25% 0.02 27);

  /* Spacing Scale */
  --sp-xs: 0.25rem;
  --sp-sm: 0.5rem;
  --sp-md: 1rem;
  --sp-lg: 1.5rem;
  --sp-xl: 2rem;
  --sp-2xl: 3rem;
  --sp-3xl: 4rem;
  --sp-4xl: 6rem;
  --sp-5xl: 8rem;

  /* Type Scale */
  --fs-xs: 0.75rem;
  --fs-sm: 0.875rem;
  --fs-base: 1rem;
  --fs-md: 1.125rem;
  --fs-lg: 1.25rem;
  --fs-xl: 1.5rem;
  --fs-2xl: 2rem;
  --fs-3xl: 2.5rem;
  --fs-4xl: 3.5rem;
  --fs-5xl: 5rem;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 150ms;
  --duration-base: 300ms;
  --duration-slow: 500ms;

  /* Layout */
  --max-width: 1200px;
  --nav-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  font-size: var(--fs-base);
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-primary);
  overflow-x: hidden;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  color: inherit;
}

ul, ol {
  list-style: none;
}

/* --- Typography --- */
.heading-xl {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-5xl);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.02em;
  text-transform: uppercase;
}

.heading-lg {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-4xl);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.01em;
  text-transform: uppercase;
}

.heading-md {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-3xl);
  font-weight: 700;
  line-height: 1.1;
  text-transform: uppercase;
}

.heading-sm {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-2xl);
  font-weight: 600;
  line-height: 1.15;
  text-transform: uppercase;
}

.heading-xs {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-xl);
  font-weight: 600;
  line-height: 1.2;
  text-transform: uppercase;
}

.text-lg { font-size: var(--fs-lg); }
.text-md { font-size: var(--fs-md); }
.text-sm { font-size: var(--fs-sm); }
.text-xs { font-size: var(--fs-xs); }

.text-accent { color: var(--accent); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-xl);
}

.section {
  padding: var(--sp-5xl) 0;
}

.section--compact {
  padding: var(--sp-3xl) 0;
}

/* --- Top Bar Promo --- */
.top-bar {
  background: var(--red);
  color: var(--white);
  text-align: center;
  padding: var(--sp-sm) var(--sp-md);
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.top-bar a {
  text-decoration: underline;
  text-underline-offset: 2px;
  margin-left: var(--sp-sm);
  font-weight: 700;
}

.top-bar a:hover {
  opacity: 0.85;
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: oklch(8% 0.01 27 / 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--nav-height);
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-xl);
}

.nav__logo {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-xl);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--white);
  flex-shrink: 0;
}

.nav__logo span {
  color: var(--red);
}

.nav__links {
  display: flex;
  align-items: center;
  gap: var(--sp-lg);
}

.nav__links a {
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-secondary);
  transition: color var(--duration-fast) ease;
  white-space: nowrap;
}

.nav__links a:hover,
.nav__links a.active {
  color: var(--white);
}

.nav__actions {
  display: flex;
  align-items: center;
  gap: var(--sp-md);
}

.nav__burger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--sp-sm);
}

.nav__burger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: all var(--duration-base) var(--ease-out);
}

.nav__burger.open span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav__burger.open span:nth-child(2) {
  opacity: 0;
}

.nav__burger.open span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile nav */
.nav__mobile {
  display: none;
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: oklch(8% 0.01 27 / 0.98);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  z-index: 999;
  padding: var(--sp-xl);
  flex-direction: column;
  gap: var(--sp-lg);
  overflow-y: auto;
}

.nav__mobile.open {
  display: flex;
}

.nav__mobile a {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-2xl);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--text-secondary);
  padding: var(--sp-sm) 0;
  border-bottom: 1px solid var(--border-color);
  transition: color var(--duration-fast) ease;
}

.nav__mobile a:hover {
  color: var(--white);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-sm);
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-md);
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: var(--sp-md) var(--sp-2xl);
  border-radius: var(--radius-sm);
  transition: all var(--duration-base) var(--ease-out);
  white-space: nowrap;
}

.btn--primary {
  background: var(--red);
  color: var(--white);
}

.btn--primary:hover {
  background: var(--red-bright);
  transform: translateY(-1px);
  box-shadow: 0 8px 24px var(--red-glow);
}

.btn--outline {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}

.btn--outline:hover {
  background: var(--white);
  color: var(--charcoal);
}

.btn--ghost {
  background: transparent;
  color: var(--white);
  border: 1px solid oklch(45% 0.02 27);
}

.btn--ghost:hover {
  border-color: var(--white);
}

.btn--sm {
  font-size: var(--fs-sm);
  padding: var(--sp-sm) var(--sp-lg);
}

.btn--lg {
  font-size: var(--fs-lg);
  padding: var(--sp-lg) var(--sp-3xl);
}

/* --- Hero Section --- */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  padding: var(--sp-4xl) var(--sp-xl);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 50% 40%, oklch(55% 0.24 27 / 0.15), transparent 70%),
    radial-gradient(ellipse 60% 80% at 20% 80%, oklch(55% 0.24 27 / 0.08), transparent 60%),
    radial-gradient(ellipse 60% 80% at 80% 80%, oklch(55% 0.24 27 / 0.08), transparent 60%);
  z-index: 0;
}

.hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, var(--bg-primary));
  z-index: 1;
}

.hero__content {
  position: relative;
  z-index: 2;
  max-width: 900px;
}

.hero__title {
  margin-bottom: var(--sp-lg);
}

.hero__title .accent {
  color: var(--red);
}

.hero__subtitle {
  font-size: var(--fs-lg);
  color: var(--text-secondary);
  max-width: 650px;
  margin: 0 auto var(--sp-2xl);
  line-height: 1.6;
}

.hero__actions {
  display: flex;
  gap: var(--sp-md);
  justify-content: center;
  flex-wrap: wrap;
}

/* --- Community Promo --- */
.community-promo {
  text-align: center;
  background: var(--bg-surface);
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
}

.community-promo__heading {
  margin-bottom: var(--sp-lg);
}

.community-promo__body {
  max-width: 680px;
  margin: 0 auto var(--sp-xl);
  color: var(--text-secondary);
  font-size: var(--fs-md);
  line-height: 1.7;
}

/* --- Two Ways --- */
.two-ways {
  text-align: center;
}

.two-ways__heading {
  margin-bottom: var(--sp-3xl);
}

.two-ways__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-xl);
}

.two-ways__card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: var(--sp-3xl) var(--sp-2xl);
  text-align: center;
  transition: all var(--duration-base) var(--ease-out);
  position: relative;
  overflow: hidden;
}

.two-ways__card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--duration-base) var(--ease-out);
}

.two-ways__card:hover::before {
  transform: scaleX(1);
}

.two-ways__card:hover {
  border-color: oklch(35% 0.04 27);
  transform: translateY(-4px);
}

.two-ways__card-label {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-xs);
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: var(--sp-lg);
}

.two-ways__card-title {
  margin-bottom: var(--sp-md);
}

.two-ways__card-body {
  color: var(--text-secondary);
  line-height: 1.7;
}

/* --- Studio Experience --- */
.studio-experience {
  text-align: center;
  position: relative;
  overflow: hidden;
}

.studio-experience::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 50% at 50% 50%, oklch(55% 0.24 27 / 0.06), transparent 70%);
  z-index: 0;
}

.studio-experience__content {
  position: relative;
  z-index: 1;
  max-width: 720px;
  margin: 0 auto;
}

.studio-experience__heading {
  margin-bottom: var(--sp-lg);
}

.studio-experience__body {
  color: var(--text-secondary);
  font-size: var(--fs-md);
  line-height: 1.7;
  margin-bottom: var(--sp-xl);
}

/* --- Free Trial CTA --- */
.free-trial {
  text-align: center;
  background: var(--red);
  position: relative;
  overflow: hidden;
}

.free-trial::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 50% 100% at 20% 50%, oklch(70% 0.26 27 / 0.3), transparent),
    radial-gradient(ellipse 50% 100% at 80% 50%, oklch(70% 0.26 27 / 0.3), transparent);
}

.free-trial__content {
  position: relative;
  z-index: 1;
}

.free-trial__heading {
  margin-bottom: var(--sp-xl);
  color: var(--white);
}

.free-trial .btn--outline {
  border-color: var(--white);
  color: var(--white);
}

.free-trial .btn--outline:hover {
  background: var(--white);
  color: var(--red);
}

/* --- Lifestyle Carousel --- */
.carousel {
  overflow: hidden;
  position: relative;
}

.carousel__heading {
  text-align: center;
  margin-bottom: var(--sp-2xl);
}

.carousel__track-wrapper {
  overflow: hidden;
  border-radius: var(--radius-lg);
}

.carousel__track {
  display: flex;
  transition: transform var(--duration-slow) var(--ease-out);
}

.carousel__slide {
  min-width: 33.333%;
  flex-shrink: 0;
  position: relative;
  aspect-ratio: 4 / 3;
  background: var(--bg-surface);
  overflow: hidden;
}

.carousel__slide-bg {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: oklch(55% 0.24 27 / 0.3);
  position: relative;
}

.carousel__slide-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, oklch(55% 0.24 27 / 0.15), oklch(12% 0.01 27 / 0.6));
}

.carousel__slide-bg span {
  position: relative;
  z-index: 1;
}

.carousel__controls {
  display: flex;
  justify-content: center;
  gap: var(--sp-md);
  margin-top: var(--sp-xl);
}

.carousel__btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--duration-base) var(--ease-out);
  color: var(--text-secondary);
  font-size: var(--fs-lg);
}

.carousel__btn:hover {
  border-color: var(--red);
  color: var(--red);
  background: oklch(55% 0.24 27 / 0.1);
}

.carousel__dots {
  display: flex;
  justify-content: center;
  gap: var(--sp-sm);
  margin-top: var(--sp-lg);
}

.carousel__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border-color);
  transition: all var(--duration-base) var(--ease-out);
  cursor: pointer;
}

.carousel__dot.active {
  background: var(--red);
  width: 24px;
  border-radius: 4px;
}

/* --- Method Overview --- */
.method-overview {
  text-align: center;
}

.method-overview__heading {
  margin-bottom: var(--sp-lg);
}

.method-overview__body {
  max-width: 720px;
  margin: 0 auto;
  color: var(--text-secondary);
  font-size: var(--fs-md);
  line-height: 1.7;
}

/* --- Weekly Schedule Table --- */
.schedule {
  overflow-x: auto;
}

.schedule__heading {
  text-align: center;
  margin-bottom: var(--sp-2xl);
}

.schedule__table {
  width: 100%;
  border-collapse: collapse;
  background: var(--bg-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border-color);
}

.schedule__table thead th {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-sm);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-secondary);
  padding: var(--sp-lg) var(--sp-xl);
  text-align: left;
  border-bottom: 2px solid var(--red);
  background: oklch(15% 0.01 27);
}

.schedule__table tbody td {
  padding: var(--sp-lg) var(--sp-xl);
  border-bottom: 1px solid var(--border-color);
  font-size: var(--fs-md);
}

.schedule__table tbody tr:last-child td {
  border-bottom: none;
}

.schedule__table tbody tr:hover {
  background: oklch(15% 0.02 27);
}

.schedule__table .day-name {
  font-family: 'Oswald', sans-serif;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--white);
}

.schedule__table .muscle-group {
  color: var(--text-secondary);
}

.schedule__table .muscle-accent {
  color: var(--red);
  font-weight: 600;
}

/* --- Floor/Treadmill Toggle --- */
.toggle-section {
  text-align: center;
}

.toggle-section__heading {
  margin-bottom: var(--sp-xl);
}

.toggle-tabs {
  display: inline-flex;
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: var(--sp-xs);
  margin-bottom: var(--sp-3xl);
}

.toggle-tab {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-md);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: var(--sp-md) var(--sp-2xl);
  border-radius: var(--radius-sm);
  transition: all var(--duration-base) var(--ease-out);
  color: var(--text-muted);
}

.toggle-tab.active {
  background: var(--red);
  color: var(--white);
}

.toggle-tab:hover:not(.active) {
  color: var(--text-primary);
}

.toggle-content {
  display: none;
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.toggle-content.active {
  display: block;
  animation: fadeIn var(--duration-base) var(--ease-out);
}

.toggle-content__title {
  margin-bottom: var(--sp-md);
}

.toggle-content__body {
  color: var(--text-secondary);
  font-size: var(--fs-md);
  line-height: 1.7;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Instructor Grid --- */
.instructors-section {
  text-align: center;
}

.instructors-section__heading {
  margin-bottom: var(--sp-3xl);
}

.filter-controls {
  display: flex;
  justify-content: center;
  gap: var(--sp-sm);
  margin-bottom: var(--sp-3xl);
  flex-wrap: wrap;
}

.filter-btn {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: var(--sp-sm) var(--sp-lg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  transition: all var(--duration-base) var(--ease-out);
  background: transparent;
}

.filter-btn:hover {
  border-color: var(--text-secondary);
  color: var(--text-primary);
}

.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--sp-xl);
}

.instructor-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--duration-base) var(--ease-out);
}

.instructor-card:hover {
  transform: translateY(-4px);
  border-color: oklch(35% 0.04 27);
  box-shadow: 0 12px 32px oklch(0% 0 0 / 0.3);
}

.instructor-card__photo {
  aspect-ratio: 1;
  background: linear-gradient(135deg, oklch(20% 0.02 27), oklch(30% 0.03 27));
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.instructor-card__photo::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, oklch(12% 0.01 27 / 0.8));
}

.instructor-card__initials {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-3xl);
  font-weight: 700;
  color: oklch(55% 0.24 27 / 0.25);
  position: relative;
  z-index: 1;
}

.instructor-card__info {
  padding: var(--sp-lg);
}

.instructor-card__name {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-lg);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  margin-bottom: var(--sp-xs);
}

.instructor-card__location {
  font-size: var(--fs-sm);
  color: var(--red);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: var(--sp-md);
}

.instructor-card__book {
  display: inline-block;
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--red);
  transition: color var(--duration-fast) ease;
}

.instructor-card__book:hover {
  color: var(--red-bright);
}

/* --- FAQ Accordion --- */
.faq-section {
  max-width: 800px;
  margin: 0 auto;
}

.faq-section__heading {
  text-align: center;
  margin-bottom: var(--sp-3xl);
}

.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-item:first-child {
  border-top: 1px solid var(--border-color);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--sp-xl) 0;
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-lg);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  text-align: left;
  color: var(--text-primary);
  transition: color var(--duration-fast) ease;
}

.faq-question:hover {
  color: var(--red);
}

.faq-question__icon {
  font-size: var(--fs-xl);
  color: var(--red);
  transition: transform var(--duration-base) var(--ease-out);
  flex-shrink: 0;
  margin-left: var(--sp-md);
}

.faq-item.open .faq-question__icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--duration-slow) var(--ease-out), padding var(--duration-slow) var(--ease-out);
}

.faq-answer__inner {
  padding-bottom: var(--sp-xl);
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: var(--fs-md);
}

.faq-item.open .faq-answer {
  max-height: 300px;
}

/* --- Digital Features --- */
.features-section {
  text-align: center;
}

.features-section__heading {
  margin-bottom: var(--sp-3xl);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--sp-xl);
}

.feature-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: var(--sp-2xl);
  text-align: center;
  transition: all var(--duration-base) var(--ease-out);
  position: relative;
}

.feature-card:hover {
  border-color: oklch(35% 0.04 27);
  transform: translateY(-4px);
}

.feature-card__icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  background: oklch(55% 0.24 27 / 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--sp-lg);
  font-size: var(--fs-2xl);
  color: var(--red);
}

.feature-card__title {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-lg);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  margin-bottom: var(--sp-md);
}

.feature-card__body {
  color: var(--text-secondary);
  font-size: var(--fs-sm);
  line-height: 1.7;
}

/* --- CTA Section --- */
.cta-section {
  text-align: center;
}

.cta-section__heading {
  margin-bottom: var(--sp-lg);
}

.cta-section__body {
  color: var(--text-secondary);
  font-size: var(--fs-md);
  max-width: 600px;
  margin: 0 auto var(--sp-xl);
  line-height: 1.7;
}

.cta-section__actions {
  display: flex;
  gap: var(--sp-md);
  justify-content: center;
  flex-wrap: wrap;
}

/* --- Newsletter --- */
.newsletter {
  text-align: center;
  border-top: 1px solid var(--border-color);
}

.newsletter__heading {
  margin-bottom: var(--sp-md);
}

.newsletter__body {
  color: var(--text-secondary);
  margin-bottom: var(--sp-xl);
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

.newsletter__form {
  display: flex;
  max-width: 480px;
  margin: 0 auto;
  gap: var(--sp-sm);
}

.newsletter__input {
  flex: 1;
  padding: var(--sp-md) var(--sp-lg);
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: var(--fs-base);
  font-family: inherit;
  outline: none;
  transition: border-color var(--duration-fast) ease;
}

.newsletter__input::placeholder {
  color: var(--text-muted);
}

.newsletter__input:focus {
  border-color: var(--red);
}

.newsletter__input.error {
  border-color: oklch(60% 0.2 25);
}

.newsletter__input.success {
  border-color: oklch(65% 0.18 145);
}

.newsletter__msg {
  font-size: var(--fs-sm);
  margin-top: var(--sp-sm);
  min-height: 1.4em;
}

.newsletter__msg.error {
  color: oklch(65% 0.2 25);
}

.newsletter__msg.success {
  color: oklch(70% 0.18 145);
}

/* --- Footer --- */
.footer {
  background: oklch(6% 0.01 27);
  border-top: 1px solid var(--border-color);
  padding: var(--sp-4xl) 0 var(--sp-xl);
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: var(--sp-3xl);
  margin-bottom: var(--sp-3xl);
}

.footer__brand-name {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-2xl);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--sp-md);
}

.footer__brand-name span {
  color: var(--red);
}

.footer__brand-body {
  color: var(--text-muted);
  font-size: var(--fs-sm);
  line-height: 1.7;
  max-width: 300px;
}

.footer__col-title {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-sm);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-secondary);
  margin-bottom: var(--sp-lg);
}

.footer__col a {
  display: block;
  font-size: var(--fs-sm);
  color: var(--text-muted);
  padding: var(--sp-xs) 0;
  transition: color var(--duration-fast) ease;
}

.footer__col a:hover {
  color: var(--white);
}

.footer__bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--sp-xl);
  border-top: 1px solid var(--border-color);
  flex-wrap: wrap;
  gap: var(--sp-md);
}

.footer__copyright {
  font-size: var(--fs-xs);
  color: var(--text-muted);
}

.footer__country {
  position: relative;
}

.footer__country-btn {
  display: flex;
  align-items: center;
  gap: var(--sp-sm);
  font-size: var(--fs-sm);
  color: var(--text-muted);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: var(--sp-sm) var(--sp-md);
  transition: all var(--duration-fast) ease;
}

.footer__country-btn:hover {
  border-color: var(--text-secondary);
  color: var(--text-primary);
}

.footer__country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  right: 0;
  background: var(--dark-gray);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  margin-bottom: var(--sp-xs);
  display: none;
  overflow: hidden;
  z-index: 100;
}

.footer__country-dropdown.open {
  display: block;
}

.footer__country-option {
  display: block;
  width: 100%;
  text-align: left;
  padding: var(--sp-sm) var(--sp-md);
  font-size: var(--fs-sm);
  color: var(--text-secondary);
  transition: all var(--duration-fast) ease;
  border: none;
  background: none;
}

.footer__country-option:hover,
.footer__country-option.active {
  background: oklch(55% 0.24 27 / 0.15);
  color: var(--white);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .heading-xl { font-size: var(--fs-4xl); }
  .heading-lg { font-size: var(--fs-3xl); }

  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .instructor-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .carousel__slide {
    min-width: 50%;
  }

  .footer__grid {
    grid-template-columns: 1fr 1fr;
    gap: var(--sp-2xl);
  }
}

@media (max-width: 768px) {
  :root {
    --nav-height: 64px;
  }

  .heading-xl { font-size: var(--fs-3xl); }
  .heading-lg { font-size: var(--fs-2xl); }
  .heading-md { font-size: var(--fs-xl); }

  .nav__links,
  .nav__actions .btn {
    display: none;
  }

  .nav__burger {
    display: flex;
  }

  .section {
    padding: var(--sp-3xl) 0;
  }

  .hero {
    min-height: 70vh;
    padding: var(--sp-3xl) var(--sp-md);
  }

  .hero__subtitle {
    font-size: var(--fs-base);
  }

  .two-ways__grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .instructor-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--sp-md);
  }

  .carousel__slide {
    min-width: 100%;
  }

  .schedule__table thead th,
  .schedule__table tbody td {
    padding: var(--sp-md);
    font-size: var(--fs-sm);
  }

  .footer__grid {
    grid-template-columns: 1fr;
    gap: var(--sp-2xl);
  }

  .newsletter__form {
    flex-direction: column;
  }

  .toggle-tabs {
    display: flex;
    width: 100%;
    max-width: 400px;
    margin-left: auto;
    margin-right: auto;
  }

  .toggle-tab {
    flex: 1;
    padding: var(--sp-md);
    font-size: var(--fs-sm);
  }

  .filter-controls {
    gap: var(--sp-xs);
  }

  .filter-btn {
    font-size: var(--fs-xs);
    padding: var(--sp-xs) var(--sp-md);
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 var(--sp-md);
  }

  .heading-xl { font-size: var(--fs-2xl); }
  .heading-lg { font-size: var(--fs-xl); }

  .hero {
    min-height: 60vh;
  }

  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .hero__actions {
    flex-direction: column;
    align-items: center;
  }

  .cta-section__actions {
    flex-direction: column;
    align-items: center;
  }
}

/* --- Utility --- */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

raw_arguments.content:
/* ============================================
   RedRoom Fitness — Design System & Styles
   ============================================ */

/* --- OKLCH Color Palette --- */
:root {
  /* Primary */
  --red: oklch(55% 0.24 27);
  --red-bright: oklch(63% 0.26 27);
  --red-dark: oklch(40% 0.2 27);
  --red-glow: oklch(55% 0.24 27 / 0.4);

  /* Neutrals */
  --black: oklch(8% 0.01 27);
  --charcoal: oklch(12% 0.01 27);
  --dark-gray: oklch(18% 0.01 27);
  --mid-gray: oklch(28% 0.01 27);
  --gray: oklch(45% 0.01 27);
  --light-gray: oklch(72% 0.01 27);
  --off-white: oklch(90% 0.005 27);
  --white: oklch(100% 0 0);

  /* Semantic */
  --bg-primary: var(--charcoal);
  --bg-surface: var(--dark-gray);
  --bg-elevated: var(--mid-gray);
  --text-primary: var(--white);
  --text-secondary: var(--light-gray);
  --text-muted: var(--gray);
  --accent: var(--red);
  --accent-hover: var(--red-bright);
  --border-color: oklch(25% 0.02 27);

  /* Spacing Scale */
  --sp-xs: 0.25rem;
  --sp-sm: 0.5rem;
  --sp-md: 1rem;
  --sp-lg: 1.5rem;
  --sp-xl: 2rem;
  --sp-2xl: 3rem;
  --sp-3xl: 4rem;
  --sp-4xl: 6rem;
  --sp-5xl: 8rem;

  /* Type Scale */
  --fs-xs: 0.75rem;
  --fs-sm: 0.875rem;
  --fs-base: 1rem;
  --fs-md: 1.125rem;
  --fs-lg: 1.25rem;
  --fs-xl: 1.5rem;
  --fs-2xl: 2rem;
  --fs-3xl: 2.5rem;
  --fs-4xl: 3.5rem;
  --fs-5xl: 5rem;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 150ms;
  --duration-base: 300ms;
  --duration-slow: 500ms;

  /* Layout */
  --max-width: 1200px;
  --nav-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  font-size: var(--fs-base);
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-primary);
  overflow-x: hidden;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  color: inherit;
}

ul, ol {
  list-style: none;
}

/* --- Typography --- */
.heading-xl {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-5xl);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.02em;
  text-transform: uppercase;
}

.heading-lg {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-4xl);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.01em;
  text-transform: uppercase;
}

.heading-md {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-3xl);
  font-weight: 700;
  line-height: 1.1;
  text-transform: uppercase;
}

.heading-sm {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-2xl);
  font-weight: 600;
  line-height: 1.15;
  text-transform: uppercase;
}

.heading-xs {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-xl);
  font-weight: 600;
  line-height: 1.2;
  text-transform: uppercase;
}

.text-lg { font-size: var(--fs-lg); }
.text-md { font-size: var(--fs-md); }
.text-sm { font-size: var(--fs-sm); }
.text-xs { font-size: var(--fs-xs); }

.text-accent { color: var(--accent); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-xl);
}

.section {
  padding: var(--sp-5xl) 0;
}

.section--compact {
  padding: var(--sp-3xl) 0;
}

/* --- Top Bar Promo --- */
.top-bar {
  background: var(--red);
  color: var(--white);
  text-align: center;
  padding: var(--sp-sm) var(--sp-md);
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.top-bar a {
  text-decoration: underline;
  text-underline-offset: 2px;
  margin-left: var(--sp-sm);
  font-weight: 700;
}

.top-bar a:hover {
  opacity: 0.85;
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: oklch(8% 0.01 27 / 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--nav-height);
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-xl);
}

.nav__logo {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-xl);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--white);
  flex-shrink: 0;
}

.nav__logo span {
  color: var(--red);
}

.nav__links {
  display: flex;
  align-items: center;
  gap: var(--sp-lg);
}

.nav__links a {
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-secondary);
  transition: color var(--duration-fast) ease;
  white-space: nowrap;
}

.nav__links a:hover,
.nav__links a.active {
  color: var(--white);
}

.nav__actions {
  display: flex;
  align-items: center;
  gap: var(--sp-md);
}

.nav__burger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--sp-sm);
}

.nav__burger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: all var(--duration-base) var(--ease-out);
}

.nav__burger.open span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav__burger.open span:nth-child(2) {
  opacity: 0;
}

.nav__burger.open span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile nav */
.nav__mobile {
  display: none;
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: oklch(8% 0.01 27 / 0.98);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  z-index: 999;
  padding: var(--sp-xl);
  flex-direction: column;
  gap: var(--sp-lg);
  overflow-y: auto;
}

.nav__mobile.open {
  display: flex;
}

.nav__mobile a {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-2xl);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--text-secondary);
  padding: var(--sp-sm) 0;
  border-bottom: 1px solid var(--border-color);
  transition: color var(--duration-fast) ease;
}

.nav__mobile a:hover {
  color: var(--white);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-sm);
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-md);
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: var(--sp-md) var(--sp-2xl);
  border-radius: var(--radius-sm);
  transition: all var(--duration-base) var(--ease-out);
  white-space: nowrap;
}

.btn--primary {
  background: var(--red);
  color: var(--white);
}

.btn--primary:hover {
  background: var(--red-bright);
  transform: translateY(-1px);
  box-shadow: 0 8px 24px var(--red-glow);
}

.btn--outline {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}

.btn--outline:hover {
  background: var(--white);
  color: var(--charcoal);
}

.btn--ghost {
  background: transparent;
  color: var(--white);
  border: 1px solid oklch(45% 0.02 27);
}

.btn--ghost:hover {
  border-color: var(--white);
}

.btn--sm {
  font-size: var(--fs-sm);
  padding: var(--sp-sm) var(--sp-lg);
}

.btn--lg {
  font-size: var(--fs-lg);
  padding: var(--sp-lg) var(--sp-3xl);
}

/* --- Hero Section --- */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  padding: var(--sp-4xl) var(--sp-xl);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 50% 40%, oklch(55% 0.24 27 / 0.15), transparent 70%),
    radial-gradient(ellipse 60% 80% at 20% 80%, oklch(55% 0.24 27 / 0.08), transparent 60%),
    radial-gradient(ellipse 60% 80% at 80% 80%, oklch(55% 0.24 27 / 0.08), transparent 60%);
  z-index: 0;
}

.hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, var(--bg-primary));
  z-index: 1;
}

.hero__content {
  position: relative;
  z-index: 2;
  max-width: 900px;
}

.hero__title {
  margin-bottom: var(--sp-lg);
}

.hero__title .accent {
  color: var(--red);
}

.hero__subtitle {
  font-size: var(--fs-lg);
  color: var(--text-secondary);
  max-width: 650px;
  margin: 0 auto var(--sp-2xl);
  line-height: 1.6;
}

.hero__actions {
  display: flex;
  gap: var(--sp-md);
  justify-content: center;
  flex-wrap: wrap;
}

/* --- Community Promo --- */
.community-promo {
  text-align: center;
  background: var(--bg-surface);
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
}

.community-promo__heading {
  margin-bottom: var(--sp-lg);
}

.community-promo__body {
  max-width: 680px;
  margin: 0 auto var(--sp-xl);
  color: var(--text-secondary);
  font-size: var(--fs-md);
  line-height: 1.7;
}

/* --- Two Ways --- */
.two-ways {
  text-align: center;
}

.two-ways__heading {
  margin-bottom: var(--sp-3xl);
}

.two-ways__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-xl);
}

.two-ways__card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: var(--sp-3xl) var(--sp-2xl);
  text-align: center;
  transition: all var(--duration-base) var(--ease-out);
  position: relative;
  overflow: hidden;
}

.two-ways__card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--duration-base) var(--ease-out);
}

.two-ways__card:hover::before {
  transform: scaleX(1);
}

.two-ways__card:hover {
  border-color: oklch(35% 0.04 27);
  transform: translateY(-4px);
}

.two-ways__card-label {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-xs);
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: var(--sp-lg);
}

.two-ways__card-title {
  margin-bottom: var(--sp-md);
}

.two-ways__card-body {
  color: var(--text-secondary);
  line-height: 1.7;
}

/* --- Studio Experience --- */
.studio-experience {
  text-align: center;
  position: relative;
  overflow: hidden;
}

.studio-experience::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 50% at 50% 50%, oklch(55% 0.24 27 / 0.06), transparent 70%);
  z-index: 0;
}

.studio-experience__content {
  position: relative;
  z-index: 1;
  max-width: 720px;
  margin: 0 auto;
}

.studio-experience__heading {
  margin-bottom: var(--sp-lg);
}

.studio-experience__body {
  color: var(--text-secondary);
  font-size: var(--fs-md);
  line-height: 1.7;
  margin-bottom: var(--sp-xl);
}

/* --- Free Trial CTA --- */
.free-trial {
  text-align: center;
  background: var(--red);
  position: relative;
  overflow: hidden;
}

.free-trial::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 50% 100% at 20% 50%, oklch(70% 0.26 27 / 0.3), transparent),
    radial-gradient(ellipse 50% 100% at 80% 50%, oklch(70% 0.26 27 / 0.3), transparent);
}

.free-trial__content {
  position: relative;
  z-index: 1;
}

.free-trial__heading {
  margin-bottom: var(--sp-xl);
  color: var(--white);
}

.free-trial .btn--outline {
  border-color: var(--white);
  color: var(--white);
}

.free-trial .btn--outline:hover {
  background: var(--white);
  color: var(--red);
}

/* --- Lifestyle Carousel --- */
.carousel {
  overflow: hidden;
  position: relative;
}

.carousel__heading {
  text-align: center;
  margin-bottom: var(--sp-2xl);
}

.carousel__track-wrapper {
  overflow: hidden;
  border-radius: var(--radius-lg);
}

.carousel__track {
  display: flex;
  transition: transform var(--duration-slow) var(--ease-out);
}

.carousel__slide {
  min-width: 33.333%;
  flex-shrink: 0;
  position: relative;
  aspect-ratio: 4 / 3;
  background: var(--bg-surface);
  overflow: hidden;
}

.carousel__slide-bg {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: oklch(55% 0.24 27 / 0.3);
  position: relative;
}

.carousel__slide-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, oklch(55% 0.24 27 / 0.15), oklch(12% 0.01 27 / 0.6));
}

.carousel__slide-bg span {
  position: relative;
  z-index: 1;
}

.carousel__controls {
  display: flex;
  justify-content: center;
  gap: var(--sp-md);
  margin-top: var(--sp-xl);
}

.carousel__btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--duration-base) var(--ease-out);
  color: var(--text-secondary);
  font-size: var(--fs-lg);
}

.carousel__btn:hover {
  border-color: var(--red);
  color: var(--red);
  background: oklch(55% 0.24 27 / 0.1);
}

.carousel__dots {
  display: flex;
  justify-content: center;
  gap: var(--sp-sm);
  margin-top: var(--sp-lg);
}

.carousel__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border-color);
  transition: all var(--duration-base) var(--ease-out);
  cursor: pointer;
}

.carousel__dot.active {
  background: var(--red);
  width: 24px;
  border-radius: 4px;
}

/* --- Method Overview --- */
.method-overview {
  text-align: center;
}

.method-overview__heading {
  margin-bottom: var(--sp-lg);
}

.method-overview__body {
  max-width: 720px;
  margin: 0 auto;
  color: var(--text-secondary);
  font-size: var(--fs-md);
  line-height: 1.7;
}

/* --- Weekly Schedule Table --- */
.schedule {
  overflow-x: auto;
}

.schedule__heading {
  text-align: center;
  margin-bottom: var(--sp-2xl);
}

.schedule__table {
  width: 100%;
  border-collapse: collapse;
  background: var(--bg-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border-color);
}

.schedule__table thead th {
  font-family: 'Oswald', sans-serif;
  font-size: var(--fs-sm);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-secondary);
  padding: var(--sp-lg) var(--sp-xl);
  text-align: left;
  border-bottom: 2px solid var(--red);
  background: oklch(15% 0.01 27);
}

.schedule__table tbody td {
  padding: var(--sp-lg) var(--sp-xl);
  border-bottom: 1px solid var(--border-color);
  font-size: var(--fs-md);
}

.schedule__table tbody tr:last-child td {
  border-bottom: none;
}

.schedule__table tbody tr:hover {
  background: oklch(15% 0.02 27);
}

.schedule__table .day-name {
  font-family: 'Oswald', sans-serif;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--white);
}

.schedule__table .muscle-group {
  color: var(--text-secondary);
